api.look('noir');
const cx=api.w/2, cy=330;
const k=api.seg(t,0,1.5);
api.glow(cx,cy,150,{c:'accent'});
api.circle(cx,cy,110,{c:'warn',w:5,k});
api.text('27 BC',cx,cy+10,{size:44,weight:'bold',align:'center',k:api.seg(t,0.8,1.8)});
api.text('Augustus, first emperor',cx,cy+160,{size:20,align:'center',c:'dim',k:api.seg(t,1.5,2.5)});
api.focus(cx,cy,api.lerp(1,1.15,api.ease(api.seg(t,0,4))));
api.say('Rome becomes an empire',0.3,3.6);

api.look('noir');
const cx=api.w/2, cy=350;
const yrs=[['27 BC',60],['117 AD',150]];
const k=api.ease(api.seg(t,0.3,3.5));
api.glow(cx,cy,120+k*100,{c:'accent'});
api.circle(cx,cy,60,{c:'warn',w:4});
api.circle(cx,cy,60+k*110,{c:'accent',w:5,fill:'accent',a:0.25});
api.circle(cx,cy,60+k*110,{c:'accent',w:5});
api.swarm(60,t,{mode:'burst',cx,cy,rx:170,ry:170,c:'warn',k:api.seg(t,0.3,4)});
api.text('27 BC',cx,cy-4,{size:24,align:'center',weight:'bold',k:api.seg(t,0,1)});
api.counter(117,cx,cy+230,{k:api.seg(t,1,3.5),suf:' AD',size:44,d:0});
api.callout('Largest: Trajan',cx+100,cy-80,cx+60,cy-250,{k:api.seg(t,3.5,4.8)});
api.say('Conquest pushes borders outward',0.3,5.5);

api.look('noir');
const cx=api.w/2;
const items=[['Roads',120000,'km'],['Trade',0,'sea'],['Peace',200,'years']];
api.text('Pax Romana',cx,170,{size:40,weight:'bold',align:'center',k:api.seg(t,0,1.2)});
api.line(40,260,api.w-40,260,{c:'line',k:api.seg(t,0.4,1.4)});
api.curve(40,360,cx,250,api.w-40,360,{c:'a2',w:5,k:api.seg(t,0.8,2.4)});
api.curve(40,440,cx,540,api.w-40,440,{c:'a3',w:5,k:api.seg(t,1.2,2.8)});
api.along([[40,360],[cx,300],[api.w-40,360]],12,t,{c:'warn'});
api.counter(200,cx,600,{k:api.seg(t,2,4),suf:' years',size:44,d:0});
api.text('of calm and trade',cx,640,{size:20,align:'center',c:'dim',k:api.seg(t,3,4)});
api.say('Two centuries of peace and trade',0.3,4.6);

api.look('noir');
const cx=api.w/2, cy=340;
const sh=api.shake(t,api.seg(t,2,4)*5);
api.circle(cx,cy,170,{c:'accent',w:5,fill:'accent',a:0.15});
const cr=[[cx-20,cy-170,cx+30,cy-70],[cx+30,cy-70,cx-10,cy+10],[cx-10,cy+10,cx+50,cy+90],[cx+50,cy+90,cx+10,cy+170]];
cr.forEach((s,i)=>api.line(s[0],s[1],s[2],s[3],{c:'bad',w:5,k:api.stag(t,i,{gap:0.5,dur:0.6,from:0.6})}));
const names=[['Plague',cx-110,cy-60],['Inflation',cx+90,cy-20],['Civil war',cx-90,cy+90]];
names.forEach((n,i)=>api.label(n[0],n[1],n[2],{k:api.stag(t,i,{gap:0.8,dur:0.5,from:2})}));
api.text('235 to 284 AD',cx,cy+240,{size:28,weight:'bold',align:'center',c:'bad',k:api.seg(t,3.5,4.5)});
api.say('Plague, coins, and war crack it',0.3,5.5);

api.look('noir');
const cx=api.w/2, cy=340;
const k=api.ease(api.seg(t,0.5,3));
api.circle(cx,cy,150,{c:'dim',w:3,dash:[6,6]});
api.line(cx,cy-170,cx,cy+170,{c:'warn',w:5,k:api.seg(t,0.3,1.2)});
const o=k*60;
api.circle(cx-o-80,cy,70,{c:'a3',w:5,fill:'a3',a:0.2});
api.circle(cx+o+80,cy,70,{c:'accent',w:5,fill:'accent',a:0.2});
api.text('West',cx-o-80,cy+8,{size:24,weight:'bold',align:'center',k:api.seg(t,1.5,2.5)});
api.text('East',cx+o+80,cy+8,{size:24,weight:'bold',align:'center',k:api.seg(t,1.5,2.5)});
api.text('Split in 285 AD',cx,cy+240,{size:26,align:'center',c:'fg',k:api.seg(t,2.5,3.5)});
api.arrow(cx-100,cy+290,cx-200,cy+290,{c:'bad',k:api.seg(t,3.5,4.5)});
api.say('Too big, so it splits in two',0.3,5.5);

api.look('noir');
const cx=api.w/2, cy=330;
const k=api.ease(api.seg(t,0.5,4));
api.circle(cx,cy,130,{c:'dim',w:3,dash:[6,6]});
api.circle(cx,cy,130*(1-k),{c:'a3',w:5,fill:'a3',a:0.2});
api.swarm(70,t,{mode:'suck',cx,cy,rx:200,ry:200,c:'bad',k:api.seg(t,0.5,5)});
api.text('West falls',cx,cy+240,{size:30,weight:'bold',align:'center',k:api.seg(t,2,3)});
api.text('476 AD',cx,cy+285,{size:44,weight:'bold',align:'center',c:'bad',k:api.seg(t,3,4)});
api.text('Last emperor deposed',cx,cy+325,{size:18,align:'center',c:'dim',k:api.seg(t,4,5)});
api.say('Rome in the West ends, 476',0.3,5.5);
